const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define southern Siberia region
  const siberia = ee.Geometry.Rectangle([80, 50, 110, 55]);

  // 2. Sentinel-2 collection with cloud mask function
  const maskClouds = (image) => {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    return image.updateMask(qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0)));
  };

  // 3. Get images for October 14, 2018 and October 29, 2018
  const col14 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(siberia)
    .filterDate('2018-10-14', '2018-10-15')
    .map(maskClouds);

  const col29 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(siberia)
    .filterDate('2018-10-29', '2018-10-30')
    .map(maskClouds);

  const size14 = col14.size().getInfo();
  const size29 = col29.size().getInfo();

  console.log(`Oct 14 Images: ${size14}, Oct 29 Images: ${size29}`);

  // 4. Check if we have data
  if (size14 === 0 || size29 === 0) {
    console.log('No data found for one or both dates.');
    console.log('C1');
    return;
  }

  // 5. Calculate NDSI (Normalized Difference Snow Index)
  const calcNDSI = (img) => {
    const green = img.select('B3');
    const swir = img.select('B11');
    const ndsi = green.subtract(swir).divide(green.add(swir)).rename('NDSI');
    return img.addBands(ndsi);
  };

  const img14 = col14.map(calcNDSI).median();
  const img29 = col29.map(calcNDSI).median();

  // 6. Calculate pixel counts and mean NDSI
  const stats14 = img14.select('NDSI').reduceRegion({
    reducer: ee.Reducer.count().combine(ee.Reducer.mean(), null, true),
    geometry: siberia,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats29 = img29.select('NDSI').reduceRegion({
    reducer: ee.Reducer.count().combine(ee.Reducer.mean(), null, true),
    geometry: siberia,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const count14 = stats14['NDSI_count'];
  const mean14 = stats14['NDSI_mean'];
  const count29 = stats29['NDSI_count'];
  const mean29 = stats29['NDSI_mean'];

  console.log(`Oct 14: Mean NDSI=${mean14?.toFixed(3)}, Pixels=${count14}`);
  console.log(`Oct 29: Mean NDSI=${mean29?.toFixed(3)}, Pixels=${count29}`);

  // 7. Validation checks
  if (count14 === 0 || count29 === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('C2');
    return;
  }

  if (mean14 === null || mean14 === undefined || mean29 === null || mean29 === undefined ||
      isNaN(mean14) || isNaN(mean29)) {
    console.log('NDSI calculation failed.');
    console.log('C3');
    return;
  }

  // 8. Compare snow cover (higher NDSI = more snow)
  const increase = mean29 > mean14;
  console.log(`Snow cover change: ${(mean29 - mean14).toFixed(4)}`);

  if (increase) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
